<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($title) ?> • Pharmacie Oganla</title><link rel="stylesheet" href="/assets/css/style.css"><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>.module-panel{background:white;border:1px solid #dce4ec;border-radius:14px;padding:22px;margin-bottom:20px;overflow:auto}.module-panel h2{margin:0 0 16px;font-size:1.15rem}.module-panel table{width:100%;border-collapse:collapse;text-align:left}.module-panel td,.module-panel th{padding:12px 8px;border-bottom:1px solid #e2e8f0;vertical-align:top}.module-panel th{font-size:.8rem;color:#60748a}.module-panel form{margin:0}.module-panel input:not([type=checkbox]):not([type=hidden]),.module-panel select{border:1px solid #cbd5e1;border-radius:8px;padding:10px;max-width:100%;background:white;color:#111827}.module-panel label{display:block;font-weight:600;margin-bottom:5px}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:15px}.fields input:not([type=checkbox]){width:100%}.module-panel .btn{display:inline-block;margin:2px;white-space:nowrap}.module-flash{padding:12px;background:#e6f7ef;border-radius:8px;margin-bottom:14px}.module-flash.error{background:#fce7eb;color:#9f1239}.module-pagination{display:flex;gap:15px;margin-top:15px}</style></head><body><div class="dashboard-shell"><aside class="sidebar"><div class="brand-box"><div class="brand-logo">Rx</div><div><div class="brand-title">Pharmacie Oganla</div><div class="brand-subtitle">Espace Officine</div></div></div><nav class="sidebar-nav"><?php foreach(['/admin'=>'Tableau de bord','/admin/medicaments/ajouter'=>'Ajouter un produit','/admin/medicaments/importer'=>'Importer CSV','/admin/reservations'=>'Réservations','/admin/pharmacies-de-garde'=>'Pharmacies de garde','/admin/utilisateurs'=>'Utilisateurs'] as $url=>$label): ?><a href="<?= $url ?>" class="nav-item <?= ($nav??parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH))===$url?'active':'' ?>"><?= $label ?></a><?php endforeach; ?></nav><?php if(isset($tauxDispo)): ?><div class="sidebar-footer-card"><div class="sf-title">Disponibilité du stock</div><div class="sf-progress"><div class="sf-progress-bar" style="width:<?= (int)$tauxDispo ?>%"></div></div><div class="sf-sub"><?= (int)$tauxDispo ?>% des références disponibles</div></div><?php endif; ?><form method="POST" action="/admin/deconnexion" class="sidebar-logout"><?= csrfField() ?><button type="submit">Déconnexion</button></form></aside><div class="workspace"><header class="workspace-header"><div class="header-left"><div class="header-title"><?= htmlspecialchars($title) ?></div></div><?php if(isset($headerAction)): ?><a class="header-btn primary-btn" href="/admin/medicaments/ajouter">+ Nouveau médicament</a><?php endif; ?></header><main class="dashboard-main"><?php if(!empty($flash)): ?><div role="status" class="module-flash <?= $flash['type']==='error'?'error':'' ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?>
